@layer base {
  :root {
    --nomos-primary: oklch(0.55 0.22 250);
    --nomos-primary-foreground: oklch(0.98 0 0);
    --nomos-secondary: oklch(0.95 0.05 250);
    --nomos-secondary-foreground: oklch(0.2 0 0);
    --nomos-background: oklch(1 0 0);
    --nomos-foreground: oklch(0.15 0 0);
    --nomos-border: oklch(0.9 0.01 250);
    --nomos-ring: oklch(0.55 0.22 250);
    --nomos-destructive: oklch(0.55 0.22 25);
    --nomos-destructive-foreground: oklch(0.98 0 0);
    --nomos-muted: oklch(0.96 0.02 250);
    --nomos-muted-foreground: oklch(0.5 0 0);
  }

  .dark {
    --nomos-primary: oklch(0.65 0.22 250);
    --nomos-primary-foreground: oklch(0.1 0 0);
    --nomos-secondary: oklch(0.25 0.08 250);
    --nomos-secondary-foreground: oklch(0.9 0 0);
    --nomos-background: oklch(0.12 0 0);
    --nomos-foreground: oklch(0.95 0 0);
    --nomos-border: oklch(0.25 0.05 250);
    --nomos-ring: oklch(0.65 0.22 250);
    --nomos-destructive: oklch(0.6 0.22 25);
    --nomos-destructive-foreground: oklch(0.98 0 0);
    --nomos-muted: oklch(0.2 0.05 250);
    --nomos-muted-foreground: oklch(0.6 0 0);
  }
}

@theme inline {
  --color-nomos-primary: var(--nomos-primary);
  --color-nomos-primary-foreground: var(--nomos-primary-foreground);
  --color-nomos-secondary: var(--nomos-secondary);
  --color-nomos-secondary-foreground: var(--nomos-secondary-foreground);
  --color-nomos-background: var(--nomos-background);
  --color-nomos-foreground: var(--nomos-foreground);
  --color-nomos-border: var(--nomos-border);
  --color-nomos-ring: var(--nomos-ring);
  --color-nomos-destructive: var(--nomos-destructive);
  --color-nomos-destructive-foreground: var(--nomos-destructive-foreground);
  --color-nomos-muted: var(--nomos-muted);
  --color-nomos-muted-foreground: var(--nomos-muted-foreground);
}
